#!/usr/bin/env bash
# scripts/verify.sh - one quality gate for this project (generated by cc-setup; edit freely)
set -u; cd "$(dirname "$0")/.." || exit 1
fail=0
step() { printf '\n== %s ==\n' "$1"; shift; "$@" || { echo "FAILED: $*"; fail=1; }; }
if [ -f package.json ]; then
  pm=npm; [ -f pnpm-lock.yaml ] && pm=pnpm; [ -f yarn.lock ] && pm=yarn
  has() { jq -e --arg s "$1" '.scripts[$s]' package.json >/dev/null 2>&1; }
  for s in lint typecheck test build; do has "$s" && step "$s" $pm run "$s"; done
  if ! has typecheck && [ -f tsconfig.json ]; then step typecheck npx --no-install tsc --noEmit; fi
fi
if [ -f composer.json ] || ls ./*.php >/dev/null 2>&1; then
  step "php lint" bash -c 'find . -name "*.php" -not -path "./vendor/*" -print0 | xargs -0 -n1 php -l >/dev/null'
fi
step "secrets" bash -c '! git grep -InE "(sb_secret_|ghp_[A-Za-z0-9]{30,}|github_pat_|-----BEGIN [A-Z ]*PRIVATE KEY-----)" -- . ":!scripts/verify.sh"'
exit $fail
